    last_updated_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_updated_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_system_message PRIMARY KEY (system_message_id)
);
CREATE INDEX ix_system_message_1 ON system_message (status_id, init_date);
CREATE INDEX ix_system_message_2 ON system_message (system_message_type_id, idempotency_key);
CREATE INDEX ix_system_message_3 ON system_message (order_id);

-- An error from one attempt to process a message.
CREATE TABLE system_message_error (
    system_message_id VARCHAR(40) NOT NULL,
    error_date TIMESTAMP(3) NOT NULL,
    attempted_status_id VARCHAR(40),
    error_text VARCHAR(4000),
    last_updated_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_updated_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_system_message_error PRIMARY KEY (system_message_id, error_date)
);

-- One import or export feed and how it runs.
CREATE TABLE data_manager_config (
    config_id VARCHAR(40) NOT NULL,
    description VARCHAR(255),
    import_service_name VARCHAR(255),
    export_service_name VARCHAR(255),
    delimiter VARCHAR(63),
    file_name_pattern VARCHAR(255),
    execution_mode_enum_id VARCHAR(40),
    multi_threading CHAR(1),
    import_path VARCHAR(255),
    export_path VARCHAR(255),
    priority BIGINT,
    last_updated_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_updated_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_data_manager_config PRIMARY KEY (config_id)
);

-- One run of a feed: files, record counts, status.
CREATE TABLE data_manager_log (
    log_id VARCHAR(40) NOT NULL,
    parent_log_id VARCHAR(40),
    config_id VARCHAR(40) NOT NULL,
    log_type_enum_id VARCHAR(40),
    status_id VARCHAR(40) NOT NULL,
    created_by_user_id VARCHAR(40),
    created_date TIMESTAMP(3),
    start_date_time TIMESTAMP(3),
    finish_date_time TIMESTAMP(3),
    cancel_date_time TIMESTAMP(3),
    job_run_id VARCHAR(40),
    upload_file_ref VARCHAR(1023),
    error_file_ref VARCHAR(1023),
    total_record_count BIGINT,
    failed_record_count BIGINT,
    last_updated_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_updated_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_tx_stamp TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_data_manager_log PRIMARY KEY (log_id)
);
CREATE INDEX ix_data_manager_log_1 ON data_manager_log (config_id, created_date);

